// Word lists and the word graph: two words are linked when they differ in
// exactly one letter. Lists are generated by scripts/build-words.py.

use std::collections::{HashMap, VecDeque};

pub const LENGTHS: [usize; 2] = [4, 5];

/// Distance value for words that can't reach each other
pub const UNREACHABLE: u32 = u32::MAX;

pub struct Dictionary {
    length: usize,
    words: Vec<&'static str>, // every allowed word, sorted
    common: Vec<usize>,       // indexes of words a puzzle may start or end on
    familiar: Vec<bool>,      // words par, hints and routes may pass through
    neighbors: Vec<Vec<usize>>,
}

fn parse(raw: &'static str) -> Vec<&'static str> {
    let mut words: Vec<&str> = raw
        .lines()
        .map(str::trim)
        .filter(|w| !w.is_empty())
        .collect();
    words.sort_unstable();
    words.dedup();
    words
}

impl Dictionary {
    pub fn new(length: usize) -> Result<Dictionary, String> {
        let (allowed, familiar, common) = match length {
            4 => (
                include_str!("words/allowed-4.txt"),
                include_str!("words/familiar-4.txt"),
                include_str!("words/common-4.txt"),
            ),
            5 => (
                include_str!("words/allowed-5.txt"),
                include_str!("words/familiar-5.txt"),
                include_str!("words/common-5.txt"),
            ),
            _ => return Err(format!("Word length must be one of {:?}", LENGTHS)),
        };
        let words = parse(allowed);
        let mut is_familiar = vec![false; words.len()];
        for w in parse(familiar) {
            if let Ok(i) = words.binary_search(&w) {
                is_familiar[i] = true;
            }
        }
        let common = parse(common)
            .into_iter()
            .filter_map(|w| words.binary_search(&w).ok())
            .collect();

        // Group words by pattern with one letter blanked ("c_ld"), then link each group
        let mut buckets: HashMap<(usize, Vec<u8>), Vec<usize>> = HashMap::new();
        for (i, word) in words.iter().enumerate() {
            for pos in 0..length {
                let mut pattern = word.as_bytes().to_vec();
                pattern[pos] = b'_';
                buckets.entry((pos, pattern)).or_default().push(i);
            }
        }
        let mut neighbors = vec![Vec::new(); words.len()];
        for group in buckets.values() {
            for &a in group {
                neighbors[a].extend(group.iter().copied().filter(|&b| b != a));
            }
        }
        for list in &mut neighbors {
            list.sort_unstable();
        }

        Ok(Dictionary {
            length,
            words,
            common,
            familiar: is_familiar,
            neighbors,
        })
    }

    pub fn length(&self) -> usize {
        self.length
    }

    pub fn word(&self, index: usize) -> &'static str {
        self.words[index]
    }

    pub fn index_of(&self, word: &str) -> Option<usize> {
        self.words.binary_search(&word).ok()
    }

    pub fn is_word(&self, word: &str) -> bool {
        self.index_of(word).is_some()
    }

    pub fn is_common(&self, index: usize) -> bool {
        self.common.binary_search(&index).is_ok()
    }

    pub fn common(&self) -> &[usize] {
        &self.common
    }

    pub fn word_count(&self) -> usize {
        self.words.len()
    }

    pub fn neighbors(&self, index: usize) -> &[usize] {
        &self.neighbors[index]
    }

    pub fn is_familiar(&self, index: usize) -> bool {
        self.familiar[index]
    }

    /// Fewest steps from `from` to every word (UNREACHABLE if there's no route).
    /// With `familiar_only`, routes pass only through familiar words; a rare
    /// word still gets a distance, as the last step of a route, but routes
    /// never continue through it.
    pub fn distances_from(&self, from: usize, familiar_only: bool) -> Vec<u32> {
        let mut dist = vec![UNREACHABLE; self.words.len()];
        let mut queue = VecDeque::from([from]);
        dist[from] = 0;
        while let Some(word) = queue.pop_front() {
            for &next in &self.neighbors[word] {
                if dist[next] == UNREACHABLE {
                    dist[next] = dist[word] + 1;
                    if !familiar_only || self.familiar[next] {
                        queue.push_back(next);
                    }
                }
            }
        }
        dist
    }
}

/// True if both words are the same length and differ in exactly one letter
pub fn one_letter_apart(a: &str, b: &str) -> bool {
    a.len() == b.len() && a.bytes().zip(b.bytes()).filter(|(x, y)| x != y).count() == 1
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_lists_load_for_every_length() {
        for length in LENGTHS {
            let dict = Dictionary::new(length).unwrap();
            assert!(dict.word_count() > 3000);
            assert!(dict.common().len() > 900);
        }
        assert!(Dictionary::new(3).is_err());
    }

    #[test]
    fn test_word_lists_are_well_formed() {
        for length in LENGTHS {
            let dict = Dictionary::new(length).unwrap();
            for i in 0..dict.word_count() {
                let w = dict.word(i);
                assert_eq!(w.len(), length, "{w}");
                assert!(w.bytes().all(|c| c.is_ascii_lowercase()), "{w}");
            }
        }
    }

    #[test]
    fn test_neighbors_differ_by_one_letter() {
        let dict = Dictionary::new(4).unwrap();
        let cold = dict.index_of("cold").unwrap();
        let next: Vec<&str> = dict.neighbors(cold).iter().map(|&i| dict.word(i)).collect();
        assert!(next.contains(&"cord"));
        assert!(next.contains(&"bold"));
        assert!(next.iter().all(|w| one_letter_apart(w, "cold")));
    }

    #[test]
    fn test_distances() {
        let dict = Dictionary::new(4).unwrap();
        let cold = dict.index_of("cold").unwrap();
        let dist = dict.distances_from(cold, true);
        assert_eq!(dist[cold], 0);
        assert_eq!(dist[dict.index_of("cord").unwrap()], 1);
        assert_eq!(dist[dict.index_of("warm").unwrap()], 4); // cold cord word ward warm
    }

    #[test]
    fn test_familiar_routes_avoid_rare_words() {
        let dict = Dictionary::new(4).unwrap();
        let coll = dict.index_of("coll").unwrap();
        assert!(!dict.is_familiar(coll));
        for &w in dict.common() {
            assert!(dict.is_familiar(w), "{}", dict.word(w));
        }
        // A rare word is still reachable, as the last step
        let cold = dict.index_of("cold").unwrap();
        assert_eq!(dict.distances_from(cold, true)[coll], 1);
    }

    #[test]
    fn test_one_letter_apart() {
        assert!(one_letter_apart("cold", "cord"));
        assert!(!one_letter_apart("cold", "cold"));
        assert!(!one_letter_apart("cold", "card"));
        assert!(!one_letter_apart("cold", "colds"));
    }
}
